#include <vector>
#include <cmath>
#include <algorithm>
#include <numeric>

class Solution {
public:
    int minimumDifference(std::vector<int>& nums) {
        int n = nums.size() / 2;
        int total = std::accumulate(nums.begin(), nums.end(), 0);
        int target = total / 2;
        std::vector<std::vector<int>> leftSums(n + 1), rightSums(n + 1);

        for (int mask = 0; mask < (1 << n); ++mask) {
            int sz = __builtin_popcount(mask);
            int sl = 0, sr = 0;
            for (int i = 0; i < n; ++i) {
                if ((mask >> i) & 1) {
                    sl += nums[i];
                    sr += nums[n + i];
                }
            }
            leftSums[sz].push_back(sl);
            rightSums[sz].push_back(sr);
        }

        for (int sz = 0; sz <= n; ++sz) {
            std::sort(rightSums[sz].begin(), rightSums[sz].end());
        }

        int ans = std::abs(total - 2 * (leftSums[n][0]));
        for (int k = 0; k <= n; ++k) {
            int req = n - k;
            const auto& rList = rightSums[req];
            for (int sl : leftSums[k]) {
                int ideal = target - sl;
                auto it = std::lower_bound(rList.begin(), rList.end(), ideal);
                if (it != rList.end()) {
                    int s1 = sl + *it;
                    ans = std::min(ans, std::abs(total - 2 * s1));
                }
                if (it != rList.begin()) {
                    int s1 = sl + *(it - 1);
                    ans = std::min(ans, std::abs(total - 2 * s1));
                }
            }
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Solution {
    public int minimumDifference(int[] nums) {
        int n = nums.length / 2;
        int total = 0;
        for (int x : nums) total += x;
        int target = total / 2;

        List<List<Integer>> leftSums = new ArrayList<>();
        List<List<Integer>> rightSums = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            leftSums.add(new ArrayList<>());
            rightSums.add(new ArrayList<>());
        }

        for (int mask = 0; mask < (1 << n); mask++) {
            int sz = Integer.bitCount(mask);
            int sl = 0, sr = 0;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1) {
                    sl += nums[i];
                    sr += nums[n + i];
                }
            }
            leftSums.get(sz).add(sl);
            rightSums.get(sz).add(sr);
        }

        for (int sz = 0; sz <= n; sz++) {
            Collections.sort(rightSums.get(sz));
        }

        int ans = Integer.MAX_VALUE;
        for (int k = 0; k <= n; k++) {
            int req = n - k;
            List<Integer> rList = rightSums.get(req);
            for (int sl : leftSums.get(k)) {
                int ideal = target - sl;
                int idx = Collections.binarySearch(rList, ideal);
                if (idx >= 0) {
                    return Math.abs(total - 2 * (sl + rList.get(idx)));
                }
                int ins = -idx - 1;
                if (ins < rList.size()) {
                    ans = Math.min(ans, Math.abs(total - 2 * (sl + rList.get(ins))));
                }
                if (ins > 0) {
                    ans = Math.min(ans, Math.abs(total - 2 * (sl + rList.get(ins - 1))));
                }
            }
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var minimumDifference = function(nums) {
    const n = Math.floor(nums.length / 2);
    let total = 0;
    for (const x of nums) total += x;
    const target = Math.floor(total / 2);

    const leftSums = Array.from({ length: n + 1 }, () => []);
    const rightSums = Array.from({ length: n + 1 }, () => []);

    for (let mask = 0; mask < (1 << n); mask++) {
        let sz = 0;
        let sl = 0, sr = 0;
        for (let i = 0; i < n; i++) {
            if ((mask >> i) & 1) {
                sz++;
                sl += nums[i];
                sr += nums[n + i];
            }
        }
        leftSums[sz].push(sl);
        rightSums[sz].push(sr);
    }

    for (let sz = 0; sz <= n; sz++) {
        rightSums[sz].sort((a, b) => a - b);
    }

    let ans = Infinity;
    for (let k = 0; k <= n; k++) {
        const req = n - k;
        const rList = rightSums[req];
        for (const sl of leftSums[k]) {
            const ideal = target - sl;
            let lo = 0, hi = rList.length;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (rList[mid] < ideal) lo = mid + 1;
                else hi = mid;
            }
            if (lo < rList.length) {
                ans = Math.min(ans, Math.abs(total - 2 * (sl + rList[lo])));
            }
            if (lo > 0) {
                ans = Math.min(ans, Math.abs(total - 2 * (sl + rList[lo - 1])));
            }
        }
    }
    return ans;
};
